4	// One schedule per repo. Which schedule depends on whether the repo has cut over to
5	// the per-repo scheduler (per-project-scheduling §3, §8):
6	//
7	// - **Cut over** (the vendored `claudinite-scheduler.yml` is present): that workflow
8	//   is the repo's ONE permitted cron, and any other `schedule:` is a competing cron.
9	//   The recurring work moves INTO a scheduler task — its steps become the task's
10	//   worker and the workflow is deleted. It is NOT converted to a dispatch-only
11	//   workflow that a task then fires: that keeps two files and two places to edit
12	//   for one job, and leaves a workflow whose only caller is the thing that replaced
13	//   it. A task IS the recurring unit after cutover, not a dispatcher for leftovers.
14	//   This stricter rule travels WITH the scheduler into a repo's mount — never before
15	//   it, so a repo mid-cutover is never falsely flagged for the crons it is about to
16	//   retire.
17	// - **Not yet cut over** (no scheduler workflow, i.e. a repo still adopting): the repo has
18	//   no sanctioned Claudinite cron yet, so only a scheduled Claudinite *executor* — a
19	//   workflow that calls a canon reusable @main — is flagged, as the shape that competes
20	//   with the scheduler the repo is about to vendor. A consumer's own unrelated scheduled
21	//   workflow is not flagged.
22	const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';
23	
24	const rule = {
25	  id: 'gha/no-scheduled-fleet-executor',
26	  severity: 'blocking',
27	  description: 'The vendored claudinite-scheduler.yml is the repo\'s only permitted cron once present — a competing cron\'s work moves into a scheduler task and the workflow goes; before it is vendored, a Claudinite executor (one that calls a canon reusable) must be workflow_dispatch-only',
28	  doc: 'packs/basics/scheduled-tasks.md',
29	  why: 'a second cron competes with the one schedule the repo is meant to have — the per-repo scheduler, which owns every recurring Claudinite job',
30	
31	  run(ctx) {
32	    const out = [];
33	    const cutOver = ctx.read(SCHEDULER_WORKFLOW) !== null;
34	    for (const wf of workflowFiles(ctx)) {
35	      if (wf === SCHEDULER_WORKFLOW) continue; // the scheduler itself is the permitted cron
36	      const text = ctx.read(wf);
37	      if (text === null) continue;
38	      if (!/^\s*schedule:/m.test(text)) continue;
39	      if (cutOver) {
40	        // The scheduler is the repo's only cron; every other recurring workflow is
41	        // dispatch-only (a scheduler task fires it).
42	        out.push(finding(rule, {
43	          file: wf,
44	          what: 'carries a `schedule:` trigger, but the vendored claudinite-scheduler.yml is this repo\'s only permitted cron',
45	          fix: 'port this workflow\'s steps into the scheduler task that owns the work and delete the workflow in the same commit — after cutover a task IS the recurring unit, so do not leave a dispatch-only workflow behind for a task to fire (per-project-scheduling §3)',
46	        }));
47	        continue;
48	      }
49	      // Pre-cutover: only a scheduled canon-reusable executor competes with the fleet routine.
50	      if (!/uses:\s*\S*\/Claudinite\/\.github\/workflows\//i.test(text)) continue;
51	      out.push(finding(rule, {
52	        file: wf,
53	        what: 'a Claudinite executor (it calls a canon reusable workflow) carries a `schedule:` trigger',
54	        fix: 'remove the schedule: trigger — make it workflow_dispatch only, and adopt the vendored claudinite-scheduler.yml, which owns every recurring Claudinite job (packs/basics/scheduled-tasks.md)',
55	      }));
56	    }
57	    return out;
58	  },
59	};
60	
61	export default rule;
